var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original regex allowed integers like '42' but the new one does not
    // This test checks that parsing '42' (without unit) should return 42
    assert.strictEqual(bytes('42'), 42);
    // But with the new regex, '42' fails to match and falls back to parseInt, which is correct
    // However, the real issue is in the regex: \d+(?:\.\d+)? matches integers and floats
    // The new regex \d(?:\.\d+)? only matches numbers with at least one digit before decimal
    // So '42' still matches because it has a digit before decimal
    // Wait - actually both regexes match '42'
    // Let's try a number like '.5': this used to be valid but now is not
    assert.strictEqual(bytes('.5kb'), 512);
    // But with the new regex, .5 does NOT match because \d(?:\.\d+)? requires a digit before decimal
    // So .5kb should parse to 512 but now returns null
    assert.strictEqual(bytes('.5kb'), 512);
  });
});

