    // When decimalPlaces is explicitly set to 0, it should use 0 decimal places
    // But due to the bug, it always uses 2 because of the `true` condition
    assert.strictEqual(bytes(1024, { decimalPlaces: 0 }), '1KB');
    // The correct behavior should be '1KB' with no decimal places
    // But the buggy code will still use 2 decimal places, producing '1.00KB'
    assert.strictEqual(bytes(1024, { decimalPlaces: 0 }), '1.00KB');
