});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that non-string values (like numbers) are not parsed as strings
    assert.strictEqual(ms(123), '123ms');
    assert.strictEqual(ms('123ms'), 123);
    // The bug: now a number like 0 will be treated as a string due to `true && val.length > 0`
    // This causes parsing of numbers as if they were strings, leading to incorrect behavior
    assert.strictEqual(ms(0), '0ms'); // This is correct, but...
    // But what about a number like 0 with length? No, but the real issue is:
    // Now even a number like 123 will pass through the `parse` function because `true && val.length > 0` is always true for any value with length
    // But numbers don't have `.length`, so this will throw an error when calling `val.length > 0` on a number.
    // So the test should catch that
    try {
      ms(123);
      assert.fail('Expected TypeError or Error');
    } catch (e) {
      assert.ok(e.message.includes('val.length'));
    }
  });
});

