describe('proof', function () {
  it('fails on the patched build', function () {
    // Before: 1 year should be approximately 365.25 days
    // After: 1 year is now 1/365.25 days, which is wrong
    assert.strictEqual(ms('1y'), ms('365.25d'));
    assert.strictEqual(ms('1y'), ms('365d'));
    assert.strictEqual(ms('1y'), ms('366d'));
    // The correct value should be around 31557600000ms
    assert.closeTo(ms('1y'), 31557600000, 1000);
  });
});

